		language: "中文",
	},
] as const

const FormSchema = z.object({
	language: z.string({
		error: "Please select a language.",
	}),
})

export default function ComboboxForm() {
	const [open, setOpen] = React.useState(false)

	const form = useForm<z.infer<typeof FormSchema>>({
		resolver: zodResolver(FormSchema),
		mode: "onSubmit",
	})

	function onSubmit(data: z.infer<typeof FormSchema>) {
		toast("You submitted the following values", {
			description: JSON.stringify(data, null, 2),
		})
	}

	const selectedLanguage = languages.find(
		(country) => country.value === form.getValues().language
	)

	return (
		<Form {...form}>
			<form onSubmit={form.handleSubmit(onSubmit)} className="space-y-3">
				<FormField
					control={form.control}
					name="language"
					render={({ field }) => (
						<FormItem className="flex flex-col">
							<FormLabel>Language</FormLabel>
							<Popover open={open} onOpenChange={setOpen}>
								<PopoverTrigger asChild>
									<FormControl>
										<Button
											variant="outline"
											color="neutral"
											role="combobox"
											aria-haspopup="listbox"
											aria-expanded={!!field.value}
											className="text-fg-tertiary w-80 font-normal">
											{selectedLanguage ? (
												<>
													<img
														src={selectedLanguage.flag}
														alt={selectedLanguage.value.toUpperCase()}
														className="size-4"
													/>
													<span className="text-fg">
														{
															languages.find(
																(language) => language.value === field.value
															)?.language
														}
													</span>
												</>
											) : (
												"Select Language"
											)}
											<ChevronDown className="text-fg-tertiary ml-auto" />
										</Button>
									</FormControl>
								</PopoverTrigger>
								<PopoverContent className="w-80 p-0">
									<Command className="border-0">
										<CommandInput placeholder="Search" className="h-9" />
										<CommandList>
											<CommandEmpty>No language found.</CommandEmpty>
											<CommandGroup>
												{languages.map((l) => (
													<CommandItem
														value={l.label}
														key={l.value}
														onSelect={() => {
															form.setValue("language", l.value, {
																shouldValidate: true,
																shouldDirty: true,
															})
															setOpen(false)
														}}>
														<img
															src={l.flag}
															alt={l.value.toUpperCase()}
															className="size-4"
														/>
														<span className="text-sm">{l.language}</span>
														<div className="ml-auto flex gap-2">
															<span className="text-fg-secondary text-[13px] font-normal">
																({l.label})
															</span>
															{l.value === field.value && <Check />}
														</div>
													</CommandItem>
												))}
											</CommandGroup>
										</CommandList>
									</Command>
								</PopoverContent>
							</Popover>
							<FormMessage />
						</FormItem>
					)}
				/>
				<Button type="submit" className="w-full">
					Set Language
				</Button>
			</form>
		</Form>
	)
}

